package com.example.practice;

import org.jpos.iso.ISOMsg;

import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;

/** Finds the messages of a day's log that an acquirer's ticket is about. */
public final class TicketSearch {

    /**
     * What the ticket says: the terminal ID, the STAN as the analyst typed it, and the moment the
     * acquirer's records say the message was sent.
     */
    public record Ticket(String terminal, String stan, Instant sent) { }

    private TicketSearch() { }

    /** Every logged message the ticket names, request and answer alike, in log order. */
    public static List<ISOMsg> find(List<ISOMsg> log, Ticket ticket) {
        List<ISOMsg> found = new ArrayList<>();
        for (ISOMsg m : log)
            if (names(ticket, m))
                found.add(m);
        return found;
    }

    /** The ticket's STAN as a message carries it. */
    static String stan(Ticket ticket) {
        return "000000".substring(ticket.stan().length()) + ticket.stan();
    }

    /** The ticket's moment as a message carries it. */
    static String sent(Ticket ticket) {
        return DateTimeFormatter.ofPattern("MMddHHmmss").withZone(ZoneOffset.UTC).format(ticket.sent());
    }

    /** Whether {@code m} is one of the messages the ticket is about. */
    static boolean names(Ticket ticket, ISOMsg m) {
        return ticket.terminal().equals(m.getString(41))
                && stan(ticket).equals(m.getString(11))
                && sent(ticket).equals(m.getString(7));
    }
}

import com.example.practice.TicketSearch;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;
import org.jpos.iso.ISOMsg;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) throws Exception {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        Logger root = Logger.getLogger("");
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            List<ISOMsg> log = new ArrayList<>();
            exchange(log, "TERM1501", "000077", "0612143005", "00");
            exchange(log, "TERM1502", "000077", "0612143005", "00");
            exchange(log, "TERM1501", "000078", "0612143140", "51");
            exchange(log, "TERM1501", "000077", "0613080012", "00");
            TicketSearch.Ticket ticket = new TicketSearch.Ticket("TERM1501", "77", Instant.parse("2026-06-12T14:30:05Z"));
            List<ISOMsg> found = TicketSearch.find(log, ticket);
            System.out.println("found for TERM1501, STAN 77, 14:30:05 UTC: " + found.size());
            for (ISOMsg m : found)
                System.out.println("  " + m.getMTI() + " 7=" + m.getString(7) + " 11=" + m.getString(11) + " 39=" + m.getString(39));
            System.out.println("found for a message never logged: "
                    + TicketSearch.find(log, new TicketSearch.Ticket("TERM1501", "79", Instant.parse("2026-06-12T14:33:00Z"))).size());
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }

    private static void exchange(List<ISOMsg> log, String terminal, String stan, String de7, String rc) throws Exception {
        ISOMsg request = new ISOMsg("0200");
        request.set(4, "000000002110");
        request.set(7, de7);
        request.set(11, stan);
        request.set(41, terminal);
        ISOMsg answer = (ISOMsg) request.clone();
        answer.setResponseMTI();
        answer.set(39, rc);
        log.add(request);
        log.add(answer);
    }
}

